exercises.solution:
function podeTreinar(idade) {
  return idade >= 16;
}

function avisoDaPorta(nome) {
  return `Bom treino, ${nome}!`;
}

test('com 16 anos pode treinar', () => {
  expect(podeTreinar(16)).toBe(true);
});

test('com 15 anos não pode treinar', () => {
  expect(podeTreinar(15)).toBe(false);
});

test('o aviso chama o aluno pelo nome', () => {
  expect(avisoDaPorta('Rui')).toBe('Bom treino, Rui!');
});

function calcularDesconto(centavos, percentual = 5) {
  return Math.round(centavos * percentual / 100);
}

test('10% de 1000 centavos são 100', () => {
  expect(calcularDesconto(1000, 10)).toBe(100);
});

test('5% de 999 centavos arredonda para 50', () => {
  expect(calcularDesconto(999, 5)).toBe(50);
});

test('sem o percentual, o desconto é de 5%', () => {
  expect(calcularDesconto(2000)).toBe(100);
});

test('o desconto é um número', () => {
  expect(typeof calcularDesconto(1000, 10)).toBe('number');
});
